function matchStaticAsset(request) {
  return caches.match(request).then(function(cached) {
    if (cached) return cached;
    return caches.match(request, { ignoreSearch: true });
  });
}

function matchOfflinePage() {
  return caches.match('/static/offline.html', { ignoreSearch: true });
}

function isOnlineProbeRequest(url, request) {
  return url.searchParams.has('__online_probe') || request.headers.get('X-BookStark-Online-Probe') === '1';
}

// Clear cached API responses
function clearApiCache() {
  return caches.open(DYNAMIC_CACHE).then(function(cache) {
    return cache.keys().then(function(keys) {
      return Promise.all(keys.map(function(request) {
        if (new URL(request.url).pathname.startsWith('/api/')) {
          return cache.delete(request);
        }
      }));
    });
  });
}

function apiCacheMetaRequest() {
  return new Request(location.origin + API_CACHE_META_URL);
}

function readApiCacheMeta(cache) {
  return cache.match(apiCacheMetaRequest()).then(function(response) {
    if (!response) return { stale: {} };
    return response.json().catch(function() { return { stale: {} }; });
  }).then(function(meta) {
    meta = meta || {};
    meta.stale = meta.stale || {};
    return meta;
  });
}

function writeApiCacheMeta(cache, meta) {
  return cache.put(apiCacheMetaRequest(), new Response(JSON.stringify(meta || { stale: {} }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

function clearApiCacheStaleFlag(request) {
  caches.open(DYNAMIC_CACHE).then(function(cache) {
    readApiCacheMeta(cache).then(function(meta) {
      if (meta.stale && meta.stale[request.url]) {
        delete meta.stale[request.url];
        return writeApiCacheMeta(cache, meta);
      }
    });
  });
}

function isOfflineQueueableMutation(url, method, request) {
  var path = url.pathname;
  if (path.indexOf('/api/ai/assistant') === 0) return false;
  if (request && request.headers && request.headers.get('X-BookStark-Offline-Policy') === 'reject') return false;
  if (path.indexOf('/verify-password') !== -1) return false;
  if (path === '/api/login' || path === '/api/register' || path === '/api/logout') return false;
  if (path.indexOf('/api/lang') === 0) return false;
  if (/^\/api\/shares\/[^/]+\/edit(?:\/|$)/.test(path)) return false;
  return true;
}

function mutationInfoForRequest(request) {
  var url = new URL(request.url);
  var path = url.pathname;
  var method = request.method;
  var info = { method: method, path: path, scopes: [], action: 'generic' };
  var blogMatch = path.match(/^\/api\/blogs\/(\d+)(?:\/([^\/]+))?$/);
  var bookMatch = path.match(/^\/api\/books\/(\d+)(?:\/.*)?$/);
  var docMatch = path.match(/^\/api\/docs\/(\d+)(?:\/.*)?$/);

  if (path.indexOf('/api/blogs') === 0) {
    info.scopes.push('blogs');
    if (method !== 'PATCH' || path.indexOf('/pin') === -1 && path.indexOf('/visibility') === -1) {
      info.scopes.push('labels');
    }
    if (blogMatch) {
      info.resourceId = blogMatch[1];
      if (blogMatch[2] === 'pin') info.action = 'blog-pin';
      else if (blogMatch[2] === 'visibility') info.action = 'blog-visibility';
      else if (method === 'DELETE') info.action = 'blog-delete';
      else if (method === 'PUT') info.action = 'blog-update';
    } else if (method === 'POST' && path === '/api/blogs') {
      info.action = 'blog-create';
    }
    return info;
  }
  if (path.indexOf('/api/books') === 0 || path.indexOf('/api/docs') === 0) {
    info.scopes.push('books', 'docs', 'labels');
    if (bookMatch) info.resourceId = bookMatch[1];
    if (docMatch) info.resourceId = docMatch[1];
    return info;
  }
  if (path.indexOf('/api/bookmarks') === 0 || path.indexOf('/api/bookmark-labels') === 0 || path.indexOf('/api/fetch-meta') === 0) {
    info.scopes.push('bookmarks', 'labels');
    return info;
  }
  if (path.indexOf('/api/labels') === 0) {
    info.scopes.push('labels', 'blogs', 'books', 'bookmarks');
    return info;
  }
  if (path.indexOf('/api/shares') === 0) {
    info.scopes.push('shares');
    if (path.indexOf('/api/shares/blog') === 0 || path === '/api/shares') info.scopes.push('blogs');
    if (path.indexOf('/api/shares/book') === 0 || path.indexOf('/api/shares/document') === 0 || path === '/api/shares') info.scopes.push('books');
    return info;
  }
  if (path.indexOf('/api/uploads') === 0) {
    info.scopes.push('uploads');
    return info;
  }
  if (path.indexOf('/api/trash') === 0) {
    info.scopes.push('trash', 'blogs', 'books', 'bookmarks', 'labels');
    return info;
  }
  if (path.indexOf('/api/profile') === 0 || path.indexOf('/api/password') === 0 || path.indexOf('/api/api-tokens') === 0) {
    info.scopes.push('profile');
    return info;
  }
  if (path.indexOf('/api/admin') === 0) {
    info.scopes.push('admin');
    return info;
  }
  info.scopes.push('all-api');
  return info;
}

function apiCacheMatchesMutation(cachedPath, info) {
  if (!cachedPath || cachedPath.indexOf('/api/') !== 0) return false;
  if (!info || info.scopes.indexOf('all-api') !== -1) return true;
  if (info.action === 'blog-pin' || info.action === 'blog-visibility') {
    return cachedPath.indexOf('/api/blogs') === 0 || cachedPath.indexOf('/api/shares') === 0;
  }
  var scopes = info.scopes || [];
  if (scopes.indexOf('blogs') !== -1 && (cachedPath.indexOf('/api/blogs') === 0 || cachedPath.indexOf('/api/shares/status') === 0)) return true;
  if (scopes.indexOf('books') !== -1 && (cachedPath.indexOf('/api/books') === 0 || cachedPath.indexOf('/api/docs') === 0 || cachedPath.indexOf('/api/shares/status') === 0)) return true;
  if (scopes.indexOf('docs') !== -1 && cachedPath.indexOf('/api/docs') === 0) return true;
  if (scopes.indexOf('bookmarks') !== -1 && (cachedPath.indexOf('/api/bookmarks') === 0 || cachedPath.indexOf('/api/bookmark-labels') === 0 || cachedPath.indexOf('/api/tags/') === 0)) return true;
  if (scopes.indexOf('labels') !== -1 && (cachedPath.indexOf('/api/labels') === 0 || cachedPath.indexOf('/api/bookmark-labels') === 0 || cachedPath.indexOf('/api/tags/') === 0)) return true;
  if (scopes.indexOf('shares') !== -1 && cachedPath.indexOf('/api/shares') === 0) return true;
  if (scopes.indexOf('uploads') !== -1 && cachedPath.indexOf('/api/uploads') === 0) return true;
  if (scopes.indexOf('trash') !== -1 && cachedPath.indexOf('/api/trash') === 0) return true;
  if (scopes.indexOf('profile') !== -1 && (cachedPath.indexOf('/api/profile') === 0 || cachedPath.indexOf('/api/api-tokens') === 0)) return true;
  if (scopes.indexOf('admin') !== -1 && cachedPath.indexOf('/api/admin') === 0) return true;
  return false;
}

function handleSuccessfulMutation(request, responseClone) {
  var info = mutationInfoForRequest(request);
  return responseClone.json().catch(function() { return null; }).then(function(payload) {
    return caches.open(DYNAMIC_CACHE).then(function(cache) {
      return patchApiCacheForMutation(cache, info, payload).then(function() {
        return markApiCacheStale(cache, info);
      });
    });
  });
}

function markApiCacheStale(cache, info) {
  return Promise.all([cache.keys(), readApiCacheMeta(cache)]).then(function(result) {
    var keys = result[0];
    var meta = result[1];
    var now = Date.now();
    keys.forEach(function(request) {
      var path = new URL(request.url).pathname;
      if (apiCacheMatchesMutation(path, info)) {
        meta.stale[request.url] = now;
      }
    });
    return writeApiCacheMeta(cache, meta);
  });
}

function patchApiCacheForMutation(cache, info, payload) {
  if (!info || !info.resourceId) return Promise.resolve();
  if (info.action === 'blog-pin') {
    return patchBlogCache(cache, info.resourceId, { is_pinned: payload && payload.data ? payload.data.is_pinned : undefined });
  }
  if (info.action === 'blog-visibility') {
    return patchBlogCache(cache, info.resourceId, { visibility: payload && payload.data ? payload.data.visibility : undefined });
  }
  if (info.action === 'blog-delete') {
    return removeBlogFromCache(cache, info.resourceId);
  }
  return Promise.resolve();
}

function patchBlogCache(cache, blogId, fields) {
  return cache.keys().then(function(keys) {
    return Promise.all(keys.map(function(request) {
      var url = new URL(request.url);
      if (url.pathname.indexOf('/api/blogs') !== 0) return Promise.resolve();
      if (isBlogListUrl(url) && !canPatchBlogList(url, fields)) return Promise.resolve();
      return cache.match(request).then(function(response) {
        if (!response) return;
        return response.clone().json().then(function(data) {
          var changed = patchBlogPayload(data, blogId, fields);
          if (!changed) return;
          return cache.put(request, jsonResponseLike(response, data));
        }).catch(function() {});
      });
    }));
  });
}

function isBlogListUrl(url) {
  return url.pathname === '/api/blogs';
}

function canPatchBlogList(url, fields) {
  if (fields.is_pinned !== undefined && url.searchParams.has('pinned')) return false;
  if (fields.visibility !== undefined && url.searchParams.has('visibility')) return false;
  return true;
}

function patchBlogPayload(data, blogId, fields) {
  var changed = false;
  function patchOne(item) {
    if (!item) return;
    var id = String(item.blog_id || item.id || '');
    if (id !== String(blogId)) return;
    Object.keys(fields).forEach(function(key) {
      if (fields[key] !== undefined && item[key] !== fields[key]) {
        item[key] = fields[key];
        changed = true;
      }
    });
  }
  if (Array.isArray(data)) {
    data.forEach(patchOne);
  } else if (Array.isArray(data && data.data)) {
    data.data.forEach(patchOne);
  } else if (data && data.data) {
    patchOne(data.data);
  }
  return changed;
}

function removeBlogFromCache(cache, blogId) {
  return cache.keys().then(function(keys) {
    return Promise.all(keys.map(function(request) {
      var url = new URL(request.url);
      if (url.pathname === '/api/blogs/' + blogId) {
        return cache.delete(request);
      }
      if (url.pathname.indexOf('/api/blogs') !== 0) return Promise.resolve();
      return cache.match(request).then(function(response) {
        if (!response) return;
        return response.clone().json().then(function(data) {
          var changed = removeBlogFromPayload(data, blogId);
          if (!changed) return;
          return cache.put(request, jsonResponseLike(response, data));
        }).catch(function() {});
      });
    }));
  });
}

function removeBlogFromPayload(data, blogId) {
  var changed = false;
  function filterList(list) {
    var next = list.filter(function(item) {
      return String((item && (item.blog_id || item.id)) || '') !== String(blogId);
    });
    if (next.length !== list.length) changed = true;
    return next;
  }
  if (Array.isArray(data)) {
    var nextRoot = filterList(data);
    data.length = 0;
    nextRoot.forEach(function(item) { data.push(item); });
  } else if (Array.isArray(data && data.data)) {
    data.data = filterList(data.data);
    if (changed) {
      adjustDeletedListMeta(data);
    }
  }
  return changed;
}

function adjustDeletedListMeta(data) {
  if (typeof data.total === 'number') {
    data.total = Math.max(0, data.total - 1);
  }
  if (typeof data.total_pages === 'number' && typeof data.page_size === 'number' && data.page_size > 0) {
    data.total_pages = Math.max(1, Math.ceil((data.total || 0) / data.page_size));
  }
}

function jsonResponseLike(response, data) {
  var headers = new Headers(response.headers);
  headers.set('Content-Type', 'application/json');
  return new Response(JSON.stringify(data), {
    status: response.status,
    statusText: response.statusText,
    headers: headers
  });
}

function resolveCachedApiResponse(event, cached, resolve) {
  caches.open(DYNAMIC_CACHE).then(function(cache) {
    readApiCacheMeta(cache).then(function(meta) {
      var stale = !!(meta.stale && meta.stale[event.request.url]);
      var headers = new Headers(cached.headers);
      headers.set('X-From-Cache', 'true');
      if (stale) {
        headers.set('X-Cache-Stale', 'true');
        notifyClient(event.clientId, {
          type: 'API_CACHE_STALE',
          url: event.request.url
        });
      }
      cached.blob().then(function(body) {
        resolve(new Response(body, {
          status: cached.status,
          statusText: cached.statusText,
          headers: headers
        }));
      });
    });
  });
}

function notifyClient(clientId, message) {
  if (!clientId || !self.clients || !self.clients.get) return;
  self.clients.get(clientId).then(function(client) {
    if (client) client.postMessage(message);
  });
}

function queueMutationRequest(request) {
  return request.clone().text().then(function(body) {
    var headers = {};
    request.headers.forEach(function(value, key) {
      headers[key] = value;
    });
    return new Promise(function(resolve, reject) {
      var req = indexedDB.open('bookstark-offline-queue', 1);
      req.onupgradeneeded = function(e) {
        var database = e.target.result;
        if (!database.objectStoreNames.contains('requests')) {
          database.createObjectStore('requests', { keyPath: 'id', autoIncrement: true });
        }
      };
      req.onsuccess = function(e) {
        var database = e.target.result;
        var tx = database.transaction('requests', 'readwrite');
        tx.objectStore('requests').add({
          url: request.url,
          method: request.method,
          headers: headers,
          body: body || null,
          timestamp: Date.now()
        });
        tx.oncomplete = function() { resolve(); };
        tx.onerror = function() { reject(tx.error); };
      };
      req.onerror = function() { reject(req.error); };
    });
  });
}

// Message handler: clear API cache on demand
self.addEventListener('message', function(event) {
  if (event.data && event.data.type === 'CLEAR_API_CACHE') {
    clearApiCache();
  }
  if (event.data && event.data.type === 'API_MUTATION_SUCCESS' && event.data.url) {
    var markPromise = caches.open(DYNAMIC_CACHE).then(function(cache) {
      return markApiCacheStale(cache, mutationInfoForRequest(new Request(event.data.url, { method: event.data.method || 'POST' })));
    });
    if (event.waitUntil) event.waitUntil(markPromise);
  }
});

// Background Sync: replay queued offline requests
self.addEventListener('sync', function(event) {
  if (event.tag === 'offline-queue') {
    event.waitUntil(replayOfflineQueue());
  }
});

function replayOfflineQueue() {
  if (self.navigator && self.navigator.locks) {
    return self.navigator.locks.request('bookstark-offline-replay', replayOfflineQueueUnlocked);
  }
  if (!replayOfflineQueue.pending) {
    replayOfflineQueue.pending = replayOfflineQueueUnlocked().finally(function() { replayOfflineQueue.pending = null; });
  }
  return replayOfflineQueue.pending;
}

function fetchQueuedWithCSRF(url, options) {
  // Queue contents must never cause a session token to be sent to another origin.
  var target = new URL(url, self.location.href);
  if (target.origin !== self.location.origin) return Promise.reject(new Error('Invalid queue origin'));
  var headers = new Headers(options.headers || {});
  if (/^Token /i.test(headers.get('Authorization') || '')) return fetch(url, options);
  function send() {
    return fetch('/api/csrf-token?_=' + Date.now(), { credentials: 'same-origin', cache: 'no-store' }).then(function(response) {
      if (!response.ok) throw new Error('CSRF refresh failed');
      return response.json();
    }).then(function(body) {
      if (!body.csrf_token) throw new Error('Missing CSRF token');
      headers.set('X-CSRF-Token', body.csrf_token);
      return fetch(url, Object.assign({}, options, { headers: headers }));
    });
  }
  return send().then(function(response) {
    if (response.status !== 403) return response;
    return response.clone().json().catch(function() { return {}; }).then(function(body) {
      return body.csrf_error === true ? send() : response;
    });
  });
}

function replayOfflineQueueUnlocked() {
  return new Promise(function(resolve, reject) {
    var req = indexedDB.open('bookstark-offline-queue', 1);
    req.onupgradeneeded = function(e) {
      var database = e.target.result;
      if (!database.objectStoreNames.contains('requests')) {
        database.createObjectStore('requests', { keyPath: 'id', autoIncrement: true });
      }
    };
    req.onsuccess = function(e) {
      var database = e.target.result;
      var tx = database.transaction('requests', 'readonly');
      var store = tx.objectStore('requests');
      var getAllReq = store.getAll();
      getAllReq.onsuccess = function() {
        var records = getAllReq.result || [];
        if (records.length === 0) { resolve(); return; }
        var chain = Promise.resolve();
        records.forEach(function(record) {
          chain = chain.then(function() {
            var opts = {
              method: record.method,
              headers: record.headers || {},
              credentials: 'same-origin'
            };
            if (record.body) opts.body = record.body;
            return fetchQueuedWithCSRF(record.url, opts).then(function(res) {
              if (res.status === 408 || res.status === 429 || res.status >= 500) {
                return;
              }
              if (res.status === 401) return;
              return (res.status === 403 ? res.clone().json().catch(function() { return {}; }) : Promise.resolve({})).then(function(body) {
                if (body.csrf_error === true) return;
                // Success or permanent client error — remove from queue.
                return new Promise(function(r) {
                  var delTx = database.transaction('requests', 'readwrite');
                  delTx.objectStore('requests').delete(record.id);
                  delTx.oncomplete = function() {
                    var mutationDone = res.ok
                      ? handleSuccessfulMutation(new Request(record.url, { method: record.method || 'POST' }), res.clone())
                      : Promise.resolve();
                    mutationDone.then(r).catch(r);
                  };
                });
              });
            }).catch(function() {
              // Network error — keep in queue for next attempt
            });
          });
        });
        chain.then(resolve).catch(resolve);
      };
      getAllReq.onerror = function() { resolve(); };
    };
    req.onerror = function() { resolve(); };
  });
}
